    a_i[11] ? 6'd43 : a_i[10] ? 6'd42 : a_i[9]  ? 6'd41 : a_i[8]  ? 6'd40 :
    a_i[7]  ? 6'd39 : a_i[6]  ? 6'd38 : a_i[5]  ? 6'd37 : a_i[4]  ? 6'd36 :
    a_i[3]  ? 6'd35 : a_i[2]  ? 6'd34 : a_i[1]  ? 6'd33 : a_i[0]  ? 6'd32 :
    6'd0;

